import { LEGACY_TIERS, NEW_TIERS } from './types';

/**
 * Returns the pricing tiers based on the 'new-pricing' feature flag.
 * Note: New tiers are pending legal review (LEGAL-212).
 */
export function getPricingTiers() {
  // Check if the new pricing feature is enabled
  // The flag is managed via Unleash

  if (flags.isEnabled('new-pricing')) return NEW_TIERS;

  return LEGACY_TIERS;
}

export const formatPrice = (amount: number, currency: string) => {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency,
  }).format(amount);
};
